def is_simple_power(x, n):
    # 1 is n**0 for any non-zero n
    if x == 1:
        return True
    # 0**k = 0 for k>0
    if n == 0:
        return x == 0
    # n == 1 => 1**k == 1, no other value is reachable
    if n == 1:
        return False
    # we only handle positive bases in the simple definition
    if x <= 0 or n < 0:
        return False

    while x % n == 0:
        x //= n
    return x == 1
