def is_samepatterns(a, b):
    """Return True if a and b have the same equality pattern.
    i.e. a[i] == a[j]  iff  b[i] == b[j] for all i, j.
    """
    if len(a) != len(b):
        return False

    map_ab = {}
    map_ba = {}
    for x, y in zip(a, b):
        # forward mapping must be consistent
        if x in map_ab:
            if map_ab[x] != y:
                return False
        else:
            map_ab[x] = y

        # reverse mapping must be consistent -> bijection
        if y in map_ba:
            if map_ba[y] != x:
                return False
        else:
            map_ba[y] = x

    return True


if __name__ == "__main__":
