The set of all substrings of the two strings is small enough to enumerate completely. With at most $31\cdot30/2$ substrings per string, the total number of pairs is under a quarter of a million, so a direct check of `a+b` being a palindrome is easily fast enough. Sorting the substrings by length allows early pruning when the remaining combinations cannot improve the current best.

```python
class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # all substrings including empty
        subs_s = ['']
        n = len(s)
        for i in range(n):
            # s[i:j] for j>i
            for j in range(i + 1, n + 1):
                subs_s.append(s[i:j])

        subs_t = ['']
        m = len(t)
        for i in range(m):
            for j in range(i + 1, m + 1):
                subs_t.append(t[i:j])

        # longest first for pruning
        subs_s.sort(key=len, reverse=True)
        subs_t.sort(key=len, reverse=True)

        best = 0
        # max length of t substring
        max_len_t = len(subs_t[0]) if subs_t else 0

        for a in subs_s:
            la = len(a)
            # even with the longest t we cannot beat best -> skip
            if la + max_len_t <= best:
                # because subs_s is decreasing, further a are shorter
                break
            for b in subs_t:
                total = la + len(b)
                if total <= best:
                    break  # b gets only shorter
                if a + b == (a + b)[::-1]:
                    best = total
        return best
```

