def minPath(grid, k):
    n = len(grid)
    # initial minimal value and positions
    min_val = None
    positions = []
    for i in range(n):
        row = grid[i]
        for j in range(n):
            v = row[j]
            if min_val is None or v < min_val:
                min_val = v
                positions = [(i, j)]
            elif v == min_val:
                positions.append((i, j))
    seq = [min_val]
    if k == 1:
        return seq

    cur_positions = set(positions)
    for _ in range(1, k):
        best = None
        # find minimal neighbour value reachable from current set
        for i, j in cur_positions:
            if i > 0:
                v = grid[i - 1][j]
                if best is None or v < best:
                    best = v
            if i + 1 < n:
                v = grid[i + 1][j]
                if v < best:
                    best = v
            if j > 0:
                v = grid[i][j - 1]
                if v < best:
                    best = v
            if j + 1 < n:
                v = grid[i][j + 1]
                if v < best:
                    best = v
        seq.append(best)
        new_positions = set()
        for i, j in cur_positions:
            if i > 0 and grid[i - 1][j] == best:
                new_positions.add((i - 1, j))
            if i + 1 < n and grid[i + 1][j] == best:
                new_positions.add((i + 1, j))
            if j > 0 and grid[i][j - 1] == best:
                new_positions.add((i, j - 1))
            if j + 1 < n and grid[i][j + 1] == best:
                new_positions.add((i, j + 1))
        cur_positions = new_positions
        if not cur_positions:  # safety, should not happen for N>=2
            break
    return seq
```

