The zigzag order is built row by row, reversing direction each time. While walking through this order we keep a global counter and keep only the cells whose counter is even, which corresponds to taking one cell and skipping the next across the whole traversal.

```python
from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        if not grid or not grid[0]:
            return []

        res = []
        path_idx = 0
        rows = len(grid)
        cols = len(grid[0])

        for i in range(rows):
            if i % 2 == 0:  # left to right
                for j in range(cols):
                    if path_idx % 2 == 0:
                        res.append(grid[i][j])
                    path_idx += 1
            else:  # right to left
                for j in range(cols - 1, -1, -1):
                    if path_idx % 2 == 0:
                        res.append(grid[i][j])
                    path_idx += 1
        return res
```

The status of each user is tracked together with the time when an offline period ends. Events are processed in chronological order, with all returns handled before any event that shares the same timestamp. Offline events make the user unavailable for the next 60 units, while message events increase counters according to the tokens `ALL`, `HERE` and `id<number>`. Sorting guarantees that offline changes precede messages at the same time, reproducing the required semantics.

```python
from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        online = [True] * numberOfUsers
        offline_end = [None] * numberOfUsers   # None means online

        parsed = []
        for ev in events:
            typ = ev[0]
            ts = int(ev[1])
            data = ev[2]
            parsed.append((ts, typ, data))

        # OFFLINE before MESSAGE at same timestamp
        parsed.sort(key=lambda x: (x[0], 0 if x[1] == 'OFFLINE' else 1))

        for ts, typ, data in parsed:
            # automatic returns
            for i in range(numberOfUsers):
                if offline_end[i] is not None and offline_end[i] <= ts:
                    online[i] = True
                    offline_end[i] = None

            if typ == 'OFFLINE':
                try:
                    uid = int(data)
                except:
                    continue
                if 0 <= uid < numberOfUsers:
                    online[uid] = False
                    offline_end[uid] = ts + 60
            else:  # MESSAGE
                tokens = data.split()
                for token in tokens:
                    if token == 'ALL':
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif token == 'HERE':
                        for i in range(numberOfUsers):
                            if online[i]:
                                mentions[i] += 1
                    elif token.startswith('id'):
                        try:
                            uid = int(token[2:])
                        except:
                            continue
                        if 0 <= uid < numberOfUsers:
                            mentions[uid] += 1
                    # unknown token -> ignore
        return mentions
```

