def rounded_avg(n, m):
    if n > m:
        return -1
    s = n + m
    if s % 2 == 0:
        rounded = s // 2
    else:
        k = s // 2  # floor of average
        # round half to even, matching Python's round
        rounded = k if k % 2 == 0 else k + 1
    return bin(rounded)
